#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Sets up the five repository secrets .github/workflows/release-macos.yml signs
# and notarizes with. Works from Linux (no Mac needed): the private key and
# certificate request are made here with openssl, Apple signs the request, and
# the .p12 is assembled here too. Re-run it to rotate the API key or renew the
# certificate; it reuses whatever an earlier run left in $WORKDIR.

TOTAL_STAGES=7

cd "$(dirname "$0")/.."
export GH_REPO="getsubwave/subwave-desktop"

# Everything this wizard writes is private and lives outside the repo.
umask 077
WORKDIR="${SUBWAVE_SIGNING_DIR:-$HOME/.local/share/subwave-signing}"
mkdir -p "$WORKDIR"
chmod 700 "$WORKDIR"
ENV_FILE="$WORKDIR/values.env"

KEY="$WORKDIR/developer-id.key.pem"
CSR="$WORKDIR/developer-id.csr"
CERT="$WORKDIR/developer-id.cert.pem"
INTERMEDIATE="$WORKDIR/DeveloperIDG2CA.pem"
APPLE_ROOT="$WORKDIR/AppleIncRootCertificate.pem"
P12="$WORKDIR/developer-id.p12"
P8="$WORKDIR/notary-api-key.p8"
CER_DOWNLOAD=""
P8_DOWNLOAD=""

ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; exit 1; }
expand_home() { printf '%s' "${1/#\~/$HOME}"; }

banner "macOS signing + notarization secrets for SUB/WAVE Desktop"

# ──────────────────────────────────────────────────────────────────────────
stage "Before you start"
say "You'll need:"
step "The Account Holder login for the Apple Developer team. Only that role can"
say "  create Developer ID certificates and App Store Connect team keys."
step "gh logged in with admin rights on $GH_REPO."
note "Working files go to $WORKDIR (private, outside the repo)."
for tool in openssl curl gh base64; do
  command -v "$tool" >/dev/null 2>&1 || fail "$tool is not installed"
done
gh auth status >/dev/null 2>&1 || fail "gh is not logged in: run gh auth login, then re-run this script"
ok "openssl, curl and gh are ready"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Private key and certificate request"
if [[ -f "$KEY" && -f "$CSR" ]]; then
  ok "reusing the key and request from an earlier run"
else
  say "Apple issues the certificate for a private key that never leaves this machine."
  ask CSR_EMAIL "Your Apple ID email:"
  ask CSR_NAME "Your name, as it should appear on the request:"
  [[ -n "$CSR_EMAIL" && -n "$CSR_NAME" ]] || fail "both are needed for the request"
  [[ "$CSR_EMAIL$CSR_NAME" != */* ]] || fail "leave '/' out of the email and name"
  write_env CSR_EMAIL "$CSR_EMAIL"
  write_env CSR_NAME "$CSR_NAME"
  openssl req -new -newkey rsa:2048 -nodes -keyout "$KEY" -out "$CSR" \
    -subj "/emailAddress=${CSR_EMAIL}/CN=${CSR_NAME}" 2>/dev/null
  ok "created $KEY"
  ok "created $CSR"
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Developer ID Application certificate"
if [[ -f "$CERT" ]]; then
  ok "reusing the certificate from an earlier run"
else
  open_url "https://developer.apple.com/account/resources/certificates/add"
  step "Choose Developer ID Application, then Continue."
  step "If it asks for a Profile Type, choose G2 Sub-CA (Xcode 11.4.1 or later)."
  step "Choose File: $CSR"
  step "Continue, then Download (usually developerID_application.cer)."
  ask CER_DOWNLOAD "Path to the downloaded .cer [~/Downloads/developerID_application.cer]:"
  CER_DOWNLOAD="$(expand_home "${CER_DOWNLOAD:-$HOME/Downloads/developerID_application.cer}")"
  [[ -f "$CER_DOWNLOAD" ]] || fail "no file at $CER_DOWNLOAD"
  openssl x509 -inform DER -in "$CER_DOWNLOAD" -out "$CERT" 2>/dev/null \
    || openssl x509 -in "$CER_DOWNLOAD" -out "$CERT" 2>/dev/null \
    || fail "$CER_DOWNLOAD is not a certificate"
fi
subject="$(openssl x509 -in "$CERT" -noout -subject)"
if [[ "$subject" != *"Developer ID Application"* ]]; then
  rm -f "$CERT"
  fail "that is not a Developer ID Application certificate ($subject)"
fi
if [[ "$(openssl x509 -in "$CERT" -noout -pubkey | openssl sha256)" != "$(openssl pkey -in "$KEY" -pubout | openssl sha256)" ]]; then
  rm -f "$CERT"
  fail "that certificate was issued for a different key; upload $CSR and download again"
fi
ok "${subject#subject=}"
ok "expires $(openssl x509 -in "$CERT" -noout -enddate | cut -d= -f2)"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Bundle the certificate for CI"
say "Checking the certificate chains to Apple, then packing key + chain into a .p12."
curl -fsSL https://www.apple.com/certificateauthority/DeveloperIDG2CA.cer | openssl x509 -inform DER -out "$INTERMEDIATE"
curl -fsSL https://www.apple.com/appleca/AppleIncRootCertificate.cer | openssl x509 -inform DER -out "$APPLE_ROOT"
openssl verify -CAfile "$APPLE_ROOT" -untrusted "$INTERMEDIATE" "$CERT" >/dev/null \
  || fail "the certificate does not chain to Apple Root CA through Developer ID G2"
ok "chains to Apple Root CA through the Developer ID G2 intermediate"

P12_PASSWORD="$(_existing P12_PASSWORD || true)"
if [[ -z "$P12_PASSWORD" || ! -f "$P12" ]]; then
  P12_PASSWORD="$(openssl rand -base64 24)"
  # SHA1/3DES rather than OpenSSL 3's AES defaults: `security import` on the
  # macOS runner has rejected the newer PKCS#12 encryption.
  P12_PASSWORD="$P12_PASSWORD" openssl pkcs12 -export \
    -inkey "$KEY" -in "$CERT" -certfile "$INTERMEDIATE" -name "Developer ID Application" \
    -keypbe PBE-SHA1-3DES -certpbe PBE-SHA1-3DES -macalg sha1 \
    -passout env:P12_PASSWORD -out "$P12"
  write_env P12_PASSWORD "$P12_PASSWORD"
fi
P12_PASSWORD="$P12_PASSWORD" openssl pkcs12 -in "$P12" -passin env:P12_PASSWORD -noout \
  || fail "$P12 does not open with the saved password; delete it and re-run"
ok "built $P12"
set_secret MACOS_CERTIFICATE_P12 "$(base64 < "$P12" | tr -d '\n')"
set_secret MACOS_CERTIFICATE_PASSWORD "$P12_PASSWORD"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Notarization API key"
if [[ ! -f "$P8" ]]; then
  open_url "https://appstoreconnect.apple.com/access/integrations/api"
  step "Open Team Keys. If it asks you to request API access first, do that."
  step "Click + to generate a key. Name: SUBWAVE Desktop notarization. Access: Developer."
  step "Copy the Issuer ID shown above the keys table, and the new key's Key ID."
  step "Download the new key. Apple allows that download only once."
fi
ask APPLE_API_ISSUER_ID "Issuer ID:"
ask APPLE_API_KEY_ID "Key ID:"
[[ "$APPLE_API_ISSUER_ID" =~ ^[0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}$ ]] \
  || fail "the Issuer ID is a UUID like 69a6de7e-…; got '$APPLE_API_ISSUER_ID'"
[[ "$APPLE_API_KEY_ID" =~ ^[A-Z0-9]{10}$ ]] \
  || fail "the Key ID is 10 capital letters and digits; got '$APPLE_API_KEY_ID'"
write_env APPLE_API_ISSUER_ID "$APPLE_API_ISSUER_ID"
write_env APPLE_API_KEY_ID "$APPLE_API_KEY_ID"
if [[ ! -f "$P8" ]]; then
  ask P8_DOWNLOAD "Path to the downloaded key [~/Downloads/AuthKey_${APPLE_API_KEY_ID}.p8]:"
  P8_DOWNLOAD="$(expand_home "${P8_DOWNLOAD:-$HOME/Downloads/AuthKey_${APPLE_API_KEY_ID}.p8}")"
  [[ -f "$P8_DOWNLOAD" ]] || fail "no file at $P8_DOWNLOAD"
  openssl pkey -in "$P8_DOWNLOAD" -noout 2>/dev/null || fail "$P8_DOWNLOAD is not a private key"
  cp "$P8_DOWNLOAD" "$P8"
fi
ok "notary key $APPLE_API_KEY_ID ready"
set_secret APPLE_API_KEY_P8 "$(cat "$P8")"
set_secret APPLE_API_KEY_ID "$APPLE_API_KEY_ID"
set_secret APPLE_API_ISSUER_ID "$APPLE_API_ISSUER_ID"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Dry run in CI"
say "Signs and notarizes the latest release's code without touching the release."
branch="$(git rev-parse --abbrev-ref HEAD)"
tag="$(gh release view --json tagName --jq .tagName)"
note "workflow from branch $branch, building $tag"
if ! git ls-remote --exit-code --heads origin "$branch" >/dev/null 2>&1; then
  warn "$branch is not on GitHub yet, so there is nothing to dispatch"
  SKIPPED+=("dry run, once $branch is pushed: gh workflow run release-macos.yml --ref $branch -f tag=$tag -f dry_run=true")
elif confirm "Start the dry run now? Both legs take about 15 minutes"; then
  gh workflow run release-macos.yml --ref "$branch" -f tag="$tag" -f dry_run=true
  sleep 8
  run_id="$(gh run list --workflow release-macos.yml --branch "$branch" --event workflow_dispatch \
    --limit 1 --json databaseId --jq '.[0].databaseId')"
  if gh run watch "$run_id" --exit-status; then
    ok "signed, notarized and verified on both legs"
    note "the DMGs: gh run download $run_id"
  else
    warn "the dry run failed: gh run view $run_id --log-failed"
    warn "fix it before backing up and deleting the working files below"
  fi
else
  SKIPPED+=("dry run: gh workflow run release-macos.yml --ref $branch -f tag=$tag -f dry_run=true")
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Back up, then clean up"
say "These are the only copies. Put them in your password manager now:"
step "$KEY  (the certificate is useless without it)"
step "$P12"
step "$ENV_FILE  (holds the .p12 password)"
step "$P8  (Apple never offers this download again)"
pause "Press Enter once they're backed up"
if confirm "Delete $WORKDIR now?"; then
  rm -rf "$WORKDIR"
  ok "deleted $WORKDIR"
else
  warn "kept $WORKDIR; it holds private keys"
fi
for downloaded in "$CER_DOWNLOAD" "$P8_DOWNLOAD"; do
  if [[ -n "$downloaded" && -f "$downloaded" ]] && confirm "Delete the downloaded $downloaded?"; then
    rm -f "$downloaded"
    ok "deleted $downloaded"
  fi
done
# ──────────────────────────────────────────────────────────────────────────

finish
